import sys

MOD = 998244353
MASK_SIZE = 1024
POPC = [0] * MASK_SIZE
for i in range(MASK_SIZE):
    POPC[i] = bin(i).count("1")


def main():
    N = sys.stdin.readline().strip()

    dp = [0] * (2 * 2 * 3 * MASK_SIZE)
    dp[((1 * 2 + 0) * 3 + 0) * MASK_SIZE + 0] = 1

    for ch in N:
        limit = ord(ch) - 48
        ndp = [0] * (2 * 2 * 3 * MASK_SIZE)

        for tight in range(2):
            for started in range(2):
                for mod in range(3):
                    base = ((tight * 2 + started) * 3 + mod) * MASK_SIZE
                    for mask in range(MASK_SIZE):
                        val = dp[base + mask]
                        if val == 0:
                            continue

                        max_d = limit if tight else 9
                        for dig in range(max_d + 1):
                            ntight = 1 if (tight and dig == limit) else 0

                            if not started and dig == 0:
                                nstarted = 0
                                nmod = 0
                                nmask = 0
                            else:
                                nstarted = 1
                                nmod = (mod * 10 + dig) % 3
                                nmask = mask | (1 << dig)

                            nidx = (((ntight * 2 + nstarted) * 3 + nmod) * MASK_SIZE + nmask)
                            nv = ndp[nidx] + val
                            if nv >= MOD:
                                nv -= MOD
                            ndp[nidx] = nv

        dp = ndp

    cnt_mod3 = 0
    cnt_has3 = 0
    cnt_exact3 = 0

    cnt_mod3_has3 = 0
    cnt_mod3_exact3 = 0
    cnt_has3_exact3 = 0
    cnt_mod3_has3_exact3 = 0

    for tight in range(2):
        for started in range(1, 2):
            for mod in range(3):
                base = ((tight * 2 + started) * 3 + mod) * MASK_SIZE
                for mask in range(MASK_SIZE):
                    val = dp[base + mask]
                    if val == 0:
                        continue

                    has3 = (mask & 8) != 0
                    distinct = POPC[mask]

                    A = (mod == 0)
                    B = has3
                    C = (distinct == 3)

                    if A:
                        cnt_mod3 += val
                        if cnt_mod3 >= MOD:
                            cnt_mod3 -= MOD
                    if B:
                        cnt_has3 += val
                        if cnt_has3 >= MOD:
                            cnt_has3 -= MOD
                    if C:
                        cnt_exact3 += val
                        if cnt_exact3 >= MOD:
                            cnt_exact3 -= MOD

                    if A and B:
                        cnt_mod3_has3 += val
                        if cnt_mod3_has3 >= MOD:
                            cnt_mod3_has3 -= MOD
                    if A and C:
                        cnt_mod3_exact3 += val
                        if cnt_mod3_exact3 >= MOD:
                            cnt_mod3_exact3 -= MOD
                    if B and C:
                        cnt_has3_exact3 += val
                        if cnt_has3_exact3 >= MOD:
                            cnt_has3_exact3 -= MOD
                    if A and B and C:
                        cnt_mod3_has3_exact3 += val
                        if cnt_mod3_has3_exact3 >= MOD:
                            cnt_mod3_has3_exact3 -= MOD

    s1 = (cnt_mod3 + cnt_has3 + cnt_exact3) % MOD
    s2 = (cnt_mod3_has3 + cnt_mod3_exact3 + cnt_has3_exact3) % MOD
    s3 = cnt_mod3_has3_exact3

    ans = (s1 - 2 * s2 + 3 * s3) % MOD
    print(ans)


if __name__ == "__main__":
    main()
