import sys
from bisect import bisect_left

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    A = data[2:2 + N]
    B = data[2 + N:2 + N + (N - 1)]

    d = [0] * (N - 1)
    for i in range(N - 1):
        d[i] = (B[i] - A[i] - A[i + 1]) % M

    c = [0] * N
    for i in range(1, N):
        c[i] = (d[i - 1] - c[i - 1]) % M

    plus_c = []   # indices even in 0-based: x_i = (a + c_i) mod M
    minus_c = []  # indices odd in 0-based: x_i = (c_i - a) mod M
    sum_c = 0

    for i, val in enumerate(c):
        sum_c += val
        if i % 2 == 0:
            plus_c.append(val)
        else:
            minus_c.append(val)

    plus_c.sort()
    minus_c.sort()

    candidates = {0, M - 1}
    for val in c:
        candidates.add(val)
        candidates.add((M - val) % M)

    diff = N & 1
    ans = 10**30

    for a in candidates:
        if a < 0 or a > M - 1:
            continue

        c_ge = len(plus_c) - bisect_left(plus_c, M - a)
        c_less = bisect_left(minus_c, a)

        cur = diff * a + sum_c - M * c_ge + M * c_less
        if cur < ans:
            ans = cur

    print(ans)

if __name__ == "__main__":
    main()

