import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))

    edges = set()
    for _ in range(M):
        a = int(next(it))
        b = int(next(it))
        if a > b:
            a, b = b, a
        edges.add((a, b))

    K = len(edges)

    deg = [0] * (N + 1)
    for a, b in edges:
        deg[a] += 1
        deg[b] += 1

    freq = [0] * (K + 1)
    for v in range(1, N + 1):
        freq[deg[v]] += 1

    E1 = 0
    E0 = 0

    for a, b in edges:
        s = deg[a] + deg[b]
        if s == K + 1:
            E1 += 1
        elif s == K:
            E0 += 1

    S = 0
    for d in range(K // 2 + 1):
        e = K - d
        if d == e:
            f = freq[d]
            if f >= 2:
                S += f * (f - 1) // 2
        else:
            S += freq[d] * freq[e]

    ans = E1 + S - E0
    print(ans)

if __name__ == "__main__":
