        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    idx = 3
    for _ in range(M):
        a = int(data[idx]) - 1
        b = int(data[idx + 1]) - 1
        idx += 2
        union(a, b)

    comps = {}
    for i, ch in enumerate(S):
        r = find(i)
        if r in comps:
            comps[r].append(ch)
        else:
            comps[r] = [ch]

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD

    invfact = [1] * (N + 1)
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    total = 1
    has_dup = False
    has_nontrivial = False

    for chars in comps.values():
        sz = len(chars)
        if sz > 1:
            has_nontrivial = True

        freq = [0] * 26
        for ch in chars:
            freq[ch - 97] += 1

        dup = False
        ways = fact[sz]
        for f in freq:
            if f > 1:
                dup = True
            if f > 0:
                ways = ways * invfact[f] % MOD

        if dup:
            has_dup = True

        total = total * ways % MOD

    if has_dup:
        ans = total
    else:
        if has_nontrivial:
            ans = total * INV2 % MOD
        else:
            ans = 1

    print(ans)

if __name__ == "__main__":
    main()

