        left = max(0, s - k + 1)
        right = min(s, N - k)

        for l in range(left, right + 1):
            r = l + k - 1
            span = coord[r] - coord[l]
            to_left = start - coord[l]
            to_right = coord[r] - start
            need = span + min(to_left, to_right)

            if need <= L:
                return True

        return False

    low, high = 1, N
    while low < high:
        mid = (low + high + 1) // 2
        if can_visit(mid):
            low = mid
        else:
            high = mid - 1

    print(low)

