import sys

sys.setrecursionlimit(1_000_000)
INF = 10**30


class SegTree:
    def __init__(self, n):
        self.n = n
        self.minv = [INF] * (4 * n)
        self.lazy = [0] * (4 * n)

    def _apply(self, idx, delta):
        self.minv[idx] += delta
        self.lazy[idx] += delta

    def _push(self, idx):
        d = self.lazy[idx]
        if d:
            self._apply(idx * 2, d)
            self._apply(idx * 2 + 1, d)
            self.lazy[idx] = 0

    def range_add(self, ql, qr, delta):
        if ql > qr:
            return
        self._range_add(1, 0, self.n - 1, ql, qr, delta)

    def _range_add(self, idx, l, r, ql, qr, delta):
        if ql <= l and r <= qr:
            self._apply(idx, delta)
            return
        self._push(idx)
        mid = (l + r) // 2
        if ql <= mid:
            self._range_add(idx * 2, l, mid, ql, qr, delta)
        if qr > mid:
            self._range_add(idx * 2 + 1, mid + 1, r, ql, qr, delta)
        self.minv[idx] = min(self.minv[idx * 2], self.minv[idx * 2 + 1])

    def point_set(self, pos, value):
        self._point_set(1, 0, self.n - 1, pos, value)

    def _point_set(self, idx, l, r, pos, value):
        if l == r:
            self.minv[idx] = value
            self.lazy[idx] = 0
            return
        self._push(idx)
        mid = (l + r) // 2
        if pos <= mid:
            self._point_set(idx * 2, l, mid, pos, value)
        else:
            self._point_set(idx * 2 + 1, mid + 1, r, pos, value)
        self.minv[idx] = min(self.minv[idx * 2], self.minv[idx * 2 + 1])

    def range_min(self, ql, qr):
        if ql > qr:
            return INF
        return self._range_min(1, 0, self.n - 1, ql, qr)

    def _range_min(self, idx, l, r, ql, qr):
        if ql <= l and r <= qr:
            return self.minv[idx]
        self._push(idx)
        mid = (l + r) // 2
        res = INF
        if ql <= mid:
            res = min(res, self._range_min(idx * 2, l, mid, ql, qr))
        if qr > mid:
            res = min(res, self._range_min(idx * 2 + 1, mid + 1, r, ql, qr))
        return res


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]
    A = data[1:]

    dp = [INF] * (N + 1)
    dp[0] = 0

    seg = SegTree(N)
    max_stack = []
    min_stack = []

    for i, x in enumerate(A):
        # Update maximums
        cur_left = i
        while max_stack and max_stack[-1][0] <= x:
            val, left = max_stack.pop()
            if left <= cur_left - 1:
                seg.range_add(left, cur_left - 1, x - val)
            cur_left = left
        max_stack.append((x, cur_left))

        # Update minimums
        cur_left = i
        while min_stack and min_stack[-1][0] >= x:
            val, left = min_stack.pop()
            if left <= cur_left - 1:
                seg.range_add(left, cur_left - 1, val - x)
            cur_left = left
        min_stack.append((x, cur_left))

        # Insert new valid start position
        if i == 1 or i >= 3:
            l = i - 1
            seg.point_set(l, dp[l] + abs(A[l] - A[i]))

        dp[i + 1] = seg.range_min(0, i)

    print(dp[N])


if __name__ == "__main__":
    solve()
