        if i == 1 or i >= 3:
            l = i - 1
            seg.point_set(l, dp[l] + abs(A[l] - A[i]))

        dp[i + 1] = seg.range_min(0, i)

    print(dp[N])


if __name__ == "__main__":
    solve()

import sys
from fractions import Fraction

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    K = int(data[1])
    A = list(map(int, data[2:2 + N]))

    points = set()

    for i in range(N - 1):
        x1 = i + 1
        x2 = i + 2
        y1 = A[i]
        y2 = A[i + 1]

        if min(y1, y2) <= K <= max(y1, y2):
            if y1 == K:
                points.add(Fraction(x1, 1))
            elif y2 == K:
                points.add(Fraction(x2, 1))
            else:
                x = Fraction(x1, 1) + Fraction(K - y1, 1) / Fraction(y2 - y1, 1)
                points.add(x)

    print(len(points))

if __name__ == "__main__":
    main()

