import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    M = next(it)
    S = next(it) - 1
    T = next(it) - 1

    graph = [[] for _ in range(N)]
    min_out = [-1] * N

    for _ in range(M):
        a = next(it) - 1
        b = next(it) - 1
        graph[a].append((b, 1))
        if min_out[a] == -1 or b < min_out[a]:
            min_out[a] = b

    for v in range(N):
        if min_out[v] != -1:
            graph[v].append((min_out[v], 0))

    INF = 10**18
    dist = [INF] * N
    dist[S] = 0
    dq = deque([S])

    while dq:
        v = dq.popleft()

        for to, cost in graph[v]:
            nd = dist[v] + cost
            if nd < dist[to]:
                dist[to] = nd
                if cost == 0:
                    dq.appendleft(to)
                else:
                    dq.append(to)

    print(dist[T] if dist[T] < INF else -1)

if __name__ == "__main__":
    main()

