import sys

MOD = 998244353
sys.setrecursionlimit(1000000)


def solve_case(N, n, m):
    def f(x, y):
        if x == y:
            return 1

        limit = (N - x) // y
        if limit == 0:
            return 1

        res = 1
        for k in range(1, limit + 1):
            res += f(y, x + k * y)
            if res >= MOD:
                res -= MOD

        return res

    return f(n, m)


def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    t = int(data[0])
    out = []
    idx = 1

    for _ in range(t):
        N = int(data[idx])
        n = int(data[idx + 1])
        m = int(data[idx + 2])
        idx += 3

        out.append(str(solve_case(N, n, m)))

    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()
